const fortStyles={rajput:{id:"rajput",name:"Rajput Forts",icon:"🏰",era:"7th–19th century CE",color:"#f97316",overview:"Built on imposing natural geography — hilltops, cliffs, and desert ridges — Rajput forts epitomize chivalric valor. Characterized by multiple concentric walls, elaborate gate systems (Pols), and intricate palace apartments within the military structure.",defenseStrategy:"Hilltop citadels exploiting natural terrain. Zigzag entry gates (Pol) with elephant-stopper spikes, catapult towers (Murar), and concealed water channels.",materials:"Yellow and red Jodhpur sandstone, granite, local limestone. Lime mortar with jaggery additive for binding strength.",artisticStyle:"Intricate Jali screens, chhatris (umbrella domes), Sheesh Mahal mirror mosaics, zenana murals in bright Rajasthani pigments.",waterSystems:"Stepped reservoirs (Kunds), hidden cisterns collecting rainwater, tunnels to natural springs within hillforts.",highlights:["Multi-layered concentric walls","Ornate Jharokha overhanging balconies","Elephants-proof spiked gates","Integrated palace-and-fort complex"],landmarks:["Mehrangarh Fort, Jodhpur","Chittorgarh Fort, Rajasthan","Amber Fort, Jaipur","Kumbhalgarh Fort, Rajasthan","Junagarh Fort, Bikaner"]},mughal:{id:"mughal",name:"Mughal Forts",icon:"🕌",era:"16th–18th century CE",color:"#8b5cf6",overview:"Mughal forts synthesized Persian, Central Asian, and Indian architectural traditions. They served simultaneously as military fortifications and royal palaces, featuring grand open courtyards, garden-pavilions, and audience halls within formidable sandstone walls.",defenseStrategy:"Massive red sandstone curtain walls (40–70 ft thick), wide moats, strategically positioned bastions for flanking fire, and underground escape tunnels.",materials:"Agra red sandstone base with white Makrana marble inlaid palace interiors. Imported Afghan lapis lazuli and Persian faience tilework on throne rooms.",artisticStyle:"Pietra Dura inlay marble work, Persian arabesques, Diwan-i-Khas open-pillared audience halls, Chini Ka Rauza Persian tile facades.",waterSystems:"Sophisticated hydraulic engineering: canal-fed central tanks, hammam baths, subterranean aqueducts, and Mughal garden chahar-bagh water channels.",highlights:["Diwan-i-Aam and Diwan-i-Khas dual courts","Red sandstone rampart walls","Intricate pietra dura marble inlays","Enclosed Mughal char-bagh gardens"],landmarks:["Agra Fort, Uttar Pradesh","Red Fort (Lal Qila), Delhi","Lahore Fort (Pakistan)","Golconda Fort, Hyderabad","Allahabad Fort, Prayagraj"]},maratha:{id:"maratha",name:"Maratha Forts",icon:"⚔️",era:"17th–19th century CE",color:"#10b981",overview:"Maratha forts were lean, strategically functional military machines optimized for guerrilla warfare across the Western Ghats. Shivaji Maharaj's genius military engineering created both inaccessible mountain forts (Giridugg) and coastal sea forts (Jaldurga) to dominate trade and defend against Mughal and British forces.",defenseStrategy:"Inaccessible vertical cliff approaches, rolling terrain bastions for crossfire, concealed sally ports for cavalry raids, and sea forts controlling coastal shipping.",materials:"Local Deccan basalt and laterite. Dry-stone coursed masonry without mortar in mountain forts for structural flexibility during earthquakes.",artisticStyle:"Minimal ornamentation — pragmatic military architecture. Occasional carved Maratha royal emblems (Gadi inscription), deity niches at entrances.",waterSystems:"Rock-cut cisterns (Hauda) carved into basalt summit plateaus, spring tapping via underground qanat channels, and coastal fort tidal pools.",highlights:["Sea forts (Jaldurga) controlling ocean lanes","Cliff-edge positioning requiring rope ladders","Minimal ornamentation for stealth","Interconnected signaling fire-tower networks"],landmarks:["Raigad Fort, Raigad","Sinhagad Fort, Pune","Pratapgad Fort, Satara","Murud-Janjira Sea Fort, Raigad","Vijaydurg Sea Fort, Sindhudurg"]},european:{id:"european",name:"European / Colonial Forts",icon:"⚓",era:"16th–19th century CE",color:"#06b6d4",overview:"Portuguese, Dutch, French, and British colonial forts introduced star-fort (trace italienne) geometry optimized for cannon warfare. Angular bastions eliminated dead zones for flanking fire, while coastal positioning prioritized naval control of trade routes over land defense.",defenseStrategy:"Star-shaped bastions eliminating cannon dead-zones, low-profile thick earthwork walls to absorb cannonball impact, moats, and overlapping fields of fire.",materials:"Laterite stone (Portuguese), brick and lime mortar (British and Dutch). Later British forts used industrial-era fired brick, wrought iron, and imported Scottish granite.",artisticStyle:"European baroque chapel facades within fort precincts, British colonial Neo-Classical officer's quarters, Portuguese Manueline stone window carvings.",waterSystems:"Fresh water cisterns with rainwater collection, underground magazines designed to remain dry, and coastal forts with desalination filtration wells.",highlights:["Star-shaped trace italienne bastion plan","Low-profile walls for cannon resistance","Coastal and river-mouth positioning","Chapel and administrative quarters within"],landmarks:["Fort Aguada, Goa","Fort St. George, Chennai","Fort William, Kolkata","Diu Fort, Daman & Diu","Chapora Fort, North Goa"]}},FEATURES=[{key:"era",label:"Historical Period"},{key:"defenseStrategy",label:"Defense Strategy"},{key:"materials",label:"Building Materials"},{key:"artisticStyle",label:"Artistic Style"},{key:"waterSystems",label:"Water Systems"},{key:"highlights",label:"Key Highlights"},{key:"landmarks",label:"Landmark Examples"}];function renderColumn(a){const e=fortStyles[a];return e?`\n        <div class="comparison-column">\n            <div class="column-header" style="background:linear-gradient(135deg,${e.color}22,${e.color}08);border-bottom:3px solid ${e.color};">\n                <span class="style-icon">${e.icon}</span>\n                <h3 style="color:${e.color}">${e.name}</h3>\n                <span class="style-era">${e.era}</span>\n            </div>\n            <div class="column-body">\n                ${FEATURES.map(a=>{const r=e[a.key];let t="";return t=Array.isArray(r)?"landmarks"===a.key?`<ul class="landmark-list">${r.map(a=>`<li>${a}</li>`).join("")}</ul>`:r.map(a=>`<span class="highlight-tag">${a}</span>`).join(""):`<span class="feature-value">${r}</span>`,`\n                        <div class="feature-row">\n                            <div class="feature-label">${a.label}</div>\n                            <div>${t}</div>\n                        </div>\n                    `}).join("")}\n            </div>\n        </div>\n    `:""}function renderComparison(){if("undefined"==typeof document)return;const a=document.getElementById("comparison-grid");if(!a)return;const e=document.getElementById("style-a")?.value||"rajput",r=document.getElementById("style-b")?.value||"mughal";a.innerHTML=renderColumn(e)+renderColumn(r)}function renderOverview(){if("undefined"==typeof document)return;const a=document.getElementById("styles-overview");a&&(a.innerHTML=Object.values(fortStyles).map(a=>`\n        <div class="style-overview-card">\n            <span class="overview-icon">${a.icon}</span>\n            <h3 style="color:${a.color}">${a.name}</h3>\n            <p class="overview-era">${a.era}</p>\n            <p class="overview-desc">${a.overview}</p>\n        </div>\n    `).join(""))}"undefined"!=typeof document&&document.addEventListener("DOMContentLoaded",()=>{renderComparison(),renderOverview(),document.getElementById("style-a")?.addEventListener("change",renderComparison),document.getElementById("style-b")?.addEventListener("change",renderComparison)}),"undefined"!=typeof module&&module.exports&&(module.exports={fortStyles:fortStyles,FEATURES:FEATURES,renderColumn:renderColumn});